/**
 * @description マスク描画中かどうか
 *              Whether the mask is being drawn
 *
 * @type {boolean}
 * @default false
 * @private
 */
let $maskDrawingState = false;
/**
 * @description マスク描画の状態をセット
 *              Set the state of mask drawing
 *
 * @param  {boolean} state
 * @return {void}
 * @method
 * @public
 */
export const $setMaskDrawing = (state) => {
    $maskDrawingState = state;
};
/**
 * @description マスク描画中かどうかを返却
 *              Returns whether the mask is being drawn
 *
 * @return {boolean}
 * @method
 * @public
 */
export const $isMaskDrawing = () => {
    return $maskDrawingState;
};
/**
 * @type {Map<number, Float32Array>}
 * @private
 */
export const $clipBounds = new Map();
/**
 * @type {Map<number, number>}
 * @private
 */
export const $clipLevels = new Map();
